#include <iostream>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    int degree[105] = {};
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        degree[u]++;
        degree[v]++;
    }

    int sum = 0;
    int oddCount = 0;
    for (int i = 1; i <= n; i++) {
        cout << "顶点 " << i << " 的度数: " << degree[i] << endl;
        sum += degree[i];
        if (degree[i] % 2 == 1) oddCount++;
    }

    cout << "度数之和: " << sum << endl;
    cout << "2 × 边数: " << 2 * m << endl;
    cout << "握手定理验证: " << (sum == 2 * m ? "正确" : "错误") << endl;
    cout << "奇度点个数: " << oddCount << (oddCount % 2 == 0 ? " (偶数，符合定理)" : " (奇数，出错)") << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    int degree[105] = {};
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        degree[u]++;
        degree[v]++;
    }

    int oddCount = 0;
    for (int i = 1; i <= n; i++) {
        if (degree[i] % 2 == 1) oddCount++;
    }

    if (oddCount == 0) {
        cout << "存在欧拉回路（所有顶点度数为偶数）" << endl;
    } else if (oddCount == 2) {
        cout << "存在欧拉路径（恰好 2 个奇度顶点）" << endl;
    } else {
        cout << "不存在欧拉路径（奇度顶点有 " << oddCount << " 个）" << endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n = 5, m = 6;
    int edges[][2] = {{1,2},{1,3},{2,3},{2,4},{3,5},{4,5}};

    bool keep[6] = {};
    keep[0] = keep[1] = keep[2] = keep[4] = true;

    cout << "原图的边:" << endl;
    for (int i = 0; i < m; i++) {
        cout << "(" << edges[i][0] << "," << edges[i][1] << ") ";
    }
    cout << endl;

    cout << "生成子图（保留所有顶点，部分边）:" << endl;
    for (int i = 0; i < m; i++) {
        if (keep[i]) {
            cout << "(" << edges[i][0] << "," << edges[i][1] << ") ";
        }
    }
    cout << endl;

    bool inV[6] = {};
    inV[1] = inV[2] = inV[3] = true;
    cout << "顶点 {1,2,3} 的导出子图:" << endl;
    for (int i = 0; i < m; i++) {
        if (inV[edges[i][0]] && inV[edges[i][1]]) {
            cout << "(" << edges[i][0] << "," << edges[i][1] << ") ";
        }
    }
    cout << endl;

    return 0;
}

#include <iostream>
#include <queue>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<int> adj[105];
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    bool visited[105] = {};
    int componentCount = 0;

    for (int start = 1; start <= n; start++) {
        if (!visited[start]) {
            componentCount++;
            queue<int> q;
            q.push(start);
            visited[start] = true;
            cout << "连通分量 " << componentCount << ": ";
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                cout << u << " ";
                for (int v : adj[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        q.push(v);
                    }
                }
            }
            cout << endl;
        }
    }

    cout << "连通分量个数: " << componentCount << endl;
    if (componentCount == 1) {
        cout << "该图是连通图" << endl;
    } else {
        cout << "该图不是连通图" << endl;
    }

    return 0;
}

