int main() {
    int n;
    cin >> n;

    int degree[105] = {};
    int m = n - 1;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        degree[u]++;
        degree[v]++;
    }

    int leafCount = 0;
    for (int i = 1; i <= n; i++) {
        if (degree[i] == 1) leafCount++;
    }

    cout << "顶点数: " << n << endl;
    cout << "边数: " << m << " (= n-1 = " << n - 1 << ")" << endl;
    cout << "叶子节点数: " << leafCount << endl;

    if (n == 1) {
        cout << "只有一个顶点，它既是根也是叶子" << endl;
    }

    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

struct Edge {
    int u, v, w;
    bool operator<(const Edge& other) const {
        return w < other.w;
    }
};

int parent[105];

int find(int x) {
    if (parent[x] != x) parent[x] = find(parent[x]);
    return parent[x];
}

void unite(int x, int y) {
    parent[find(x)] = find(y);
}

int main() {
    int n, m;
    cin >> n >> m;

    Edge edges[5005];
    for (int i = 0; i < m; i++) {
        cin >> edges[i].u >> edges[i].v >> edges[i].w;
    }

    sort(edges, edges + m);

    for (int i = 1; i <= n; i++) parent[i] = i;

    int totalWeight = 0;
    int edgeCount = 0;

    for (int i = 0; i < m && edgeCount < n - 1; i++) {
        int u = edges[i].u, v = edges[i].v, w = edges[i].w;
        if (find(u) != find(v)) {
            unite(u, v);
            totalWeight += w;
            edgeCount++;
            cout << "选边: (" << u << "," << v << ") 权值=" << w << endl;
        }
    }

    cout << "最小生成树总权值: " << totalWeight << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    int inDeg[105] = {};
    int outDeg[105] = {};

    cout << "有向图的边:" << endl;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        outDeg[u]++;
        inDeg[v]++;
        cout << u << " -> " << v << endl;
    }

    int sumIn = 0, sumOut = 0;
    for (int i = 1; i <= n; i++) {
        sumIn += inDeg[i];
        sumOut += outDeg[i];
        cout << "顶点 " << i << ": 入度=" << inDeg[i]
             << " 出度=" << outDeg[i]
             << " 总度数=" << inDeg[i] + outDeg[i] << endl;
    }

    cout << "入度之和: " << sumIn << endl;
    cout << "出度之和: " << sumOut << endl;
    cout << "边数: " << m << endl;
    cout << "验证: " << (sumIn == sumOut && sumIn == m ? "正确" : "错误") << endl;

    return 0;
}

#include <iostream>
#include <queue>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<int> adj[105];
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    int color[105];
    for (int i = 1; i <= n; i++) color[i] = -1;

    bool isBipartite = true;

    for (int start = 1; start <= n; start++) {
        if (color[start] != -1) continue;

        color[start] = 0;
        queue<int> q;
        q.push(start);

        while (!q.empty() && isBipartite) {
            int u = q.front();
            q.pop();
            for (int v : adj[u]) {
                if (color[v] == -1) {
                    color[v] = 1 - color[u];
                    q.push(v);
                } else if (color[v] == color[u]) {
                    isBipartite = false;
                    break;
                }
            }
        }
    }

    if (isBipartite) {
        cout << "是二分图" << endl;
        cout << "集合 X: ";
        for (int i = 1; i <= n; i++) if (color[i] == 0) cout << i << " ";
        cout << endl;
        cout << "集合 Y: ";
        for (int i = 1; i <= n; i++) if (color[i] == 1) cout << i << " ";
        cout << endl;
    } else {
        cout << "不是二分图" << endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

int n, m;
int adj[105][105] = {};
int color[105];

bool isSafe(int v, int c) {
    for (int i = 1; i <= n; i++) {
        if (adj[v][i] && color[i] == c) return false;
    }
    return true;
}

bool solve(int v, int maxColor) {
    if (v > n) return true;
    for (int c = 1; c <= maxColor; c++) {
        if (isSafe(v, c)) {
            color[v] = c;
            if (solve(v + 1, maxColor)) return true;
            color[v] = 0;
        }
    }
    return false;
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u][v] = 1;
        adj[v][u] = 1;
    }

    for (int maxColor = 1; maxColor <= n; maxColor++) {
        for (int i = 1; i <= n; i++) color[i] = 0;
        if (solve(1, maxColor)) {
            cout << "色数: " << maxColor << endl;
            for (int i = 1; i <= n; i++) {
                cout << "顶点 " << i << " -> 颜色 " << color[i] << endl;
            }
            break;
        }
    }

    return 0;
}
